func (q *Queries) ListEventsForUser(ctx context.Context, arg ListEventsForUserParams) ([]ListEventsForUserRow, error) {
	rows, err := q.db.Query(ctx, listEventsForUser,
		arg.UserID,
		arg.CursorCreatedAt,
		arg.CursorID,
		arg.Lim,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListEventsForUserRow{}
	for rows.Next() {
		var i ListEventsForUserRow
		if err := rows.Scan(
			&i.ID,
			&i.Slug,
			&i.Title,
			&i.OccasionSlug,
			&i.Status,
			&i.StartsAt,
			&i.CreatedAt,
			&i.Role,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

