// Editor save for owners and editors. NULL content/overrides/template leave that part unchanged;
// title, starts_at and ends_at are derived from content and only change with it. Moving ends_at
// restarts retention from greatest(new end, now()) (so back-dating never shortens an event's life)
// and clears the reminder so the new end gets its own. A template change must
// resolve (with the unchanged half) to a selectable pin; leaving both NULL keeps an existing pin even
// if that template has since become premium or retired. An unselectable pin updates no row.
func (q *Queries) UpdateEventContent(ctx context.Context, arg UpdateEventContentParams) (UpdateEventContentRow, error) {
	row := q.db.QueryRow(ctx, updateEventContent,
		arg.Content,
		arg.Title,
		arg.StartsAt,
		arg.EndsAt,
		arg.Overrides,
		arg.TemplateID,
		arg.TemplateVersion,
		arg.EventID,
		arg.Version,
		arg.UserID,
	)
	var i UpdateEventContentRow
	err := row.Scan(&i.Version, &i.UpdatedAt)
	return i, err
}

const updateEventSettings = `-- name: UpdateEventSettings :one
UPDATE events e
SET slug = coalesce($1, e.slug),
    visibility = coalesce($2, e.visibility),
    password_hash = CASE
        WHEN coalesce($2::text, e.visibility) <> 'password' THEN NULL
        ELSE coalesce($3::text, e.password_hash)
    END,
    rsvp_mode = coalesce($4, e.rsvp_mode),
    notify_rsvps = coalesce($5, e.notify_rsvps),
    version = e.version + 1,
    updated_at = now()
WHERE e.id = $6
  AND e.owner_id = $7::uuid
  AND e.deleted_at IS NULL
  AND e.version = $8
  AND e.status <> 'taken_down'
RETURNING e.version, e.updated_at
`

type UpdateEventSettingsParams struct {
	Slug         *string   `json:"slug"`
	Visibility   *string   `json:"visibility"`
	PasswordHash *string   `json:"password_hash"`
	RsvpMode     *string   `json:"rsvp_mode"`
	NotifyRsvps  *bool     `json:"notify_rsvps"`
	EventID      uuid.UUID `json:"event_id"`
	UserID       uuid.UUID `json:"user_id"`
	Version      int32     `json:"version"`
}

type UpdateEventSettingsRow struct {
	Version   int32     `json:"version"`
	UpdatedAt time.Time `json:"updated_at"`
}

// Owner only. NULL leaves a field unchanged. The password hash is kept only while visibility is
// 'password' (the CHECKs require that); a new hash replaces the old one. Changing the slug of a
// published event raises check_violation on constraint events_slug_immutable.
func (q *Queries) UpdateEventSettings(ctx context.Context, arg UpdateEventSettingsParams) (UpdateEventSettingsRow, error) {
	row := q.db.QueryRow(ctx, updateEventSettings,
		arg.Slug,
		arg.Visibility,
		arg.PasswordHash,
		arg.RsvpMode,
		arg.NotifyRsvps,
		arg.EventID,
		arg.UserID,
		arg.Version,
	)
	var i UpdateEventSettingsRow
	err := row.Scan(&i.Version, &i.UpdatedAt)
	return i, err
}
